// Accessibility Conformance Report partials, generated by scripts/acr-to-html.mjs from each
// project's vendored docs/ACR.md (src/data/acr/<slug>/). A study shows one when its slug has a partial.
const partials = import.meta.glob<string>('./acr/*/acr.html', { query: '?raw', import: 'default', eager: true });

export function getAcrHtml(slug: string): string | undefined {
  return partials[`./acr/${slug}/acr.html`];
}
